"""Figures used in the README (all regenerated by `python -m vm2c`)."""
from __future__ import annotations

from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402

from .model import SAMPLE  # noqa: E402

COLOR = {"S": "#E8002D", "M": "#F5B800", "H": "#8A8F98"}
NAME = {"S": "Soft", "M": "Medium", "H": "Hard"}
plt.rcParams.update({"figure.dpi": 140, "axes.spines.top": False, "axes.spines.right": False,
                     "axes.grid": True, "grid.alpha": 0.25, "font.size": 9.5})


def _save(fig, path: Path):
    fig.tight_layout()
    fig.savefig(path, bbox_inches="tight", facecolor="white")
    plt.close(fig)


def tyre_model(path: Path, track=SAMPLE):
    fig, ax = plt.subplots(figsize=(7.5, 3.6))
    for c, t in track.tyres.items():
        k = np.arange(1, t.L + 12)
        ax.plot(k, [t.lap(int(i)) for i in k], color=COLOR[c], lw=2.2,
                label=f"{NAME[c]}  B={t.B:g}, d={t.d:g}, L={t.L}, D={t.D:g}")
        ax.axvline(t.L, color=COLOR[c], ls=":", lw=1)
    ax.set(ylim=(79, 99), xlabel="tyre age k (lap of the stint)", ylabel="lap time $t_c(k)$ (s)",
           title="Piecewise-linear tyre model with a performance cliff (sample track)")
    ax.legend(frameon=False, fontsize=8)
    _save(fig, path)


def single_compound(path: Path, rows: dict, track=SAMPLE):
    """rows: compound -> list of (m, T)."""
    fig, ax = plt.subplots(figsize=(7.5, 3.6))
    for c, pts in rows.items():
        m, T = zip(*pts)
        ax.plot(m, T, "-o", color=COLOR[c], ms=4, label=NAME[c])
        i = int(np.argmin(T))
        ax.scatter([m[i]], [T[i]], s=140, facecolors="none", edgecolors=COLOR[c], lw=2)
        ax.annotate(f"{T[i]:.1f} s", (m[i], T[i]), xytext=(6, -12), textcoords="offset points", color=COLOR[c])
    ax.set(ylim=(4100, 4360), xlabel="stints m (m-1 pit stops)", ylabel="race time T (s)",
           title=f"A1 - one compound only (N={track.N}, P={track.P:g})")
    ax.legend(frameon=False)
    _save(fig, path)


def cost_rate(path: Path, track=SAMPLE):
    fig, ax = plt.subplots(figsize=(7.5, 3.6))
    for c, t in track.tyres.items():
        n = np.arange(4, min(t.L + 11, track.N) + 1)
        r = [(t.stint(int(i)) + track.P) / i for i in n]
        ax.plot(n, r, color=COLOR[c], lw=2, label=NAME[c])
        j = int(np.argmin(r))
        ax.plot(n[j], r[j], "o", color=COLOR[c], ms=7)
        ax.annotate(f"{NAME[c][0]}{n[j]}: {r[j]:.4f}", (n[j], r[j]), xytext=(4, 6), textcoords="offset points",
                    color=COLOR[c])
    ax.set(ylim=(82.8, 86), xlabel="stint length n (laps)", ylabel="$(S_c(n)+P)/n$  (s/lap)",
           title="A2 - pit-amortised cost per lap; minimum near $\\sqrt{2P/d_c}$, capped by $L_c$")
    ax.legend(frameon=False)
    _save(fig, path)


def pit_envelope(path: Path, A: list, deltas: list, P_mark: float = 25.0):
    fig, (ax, bx) = plt.subplots(1, 2, figsize=(10, 3.6))
    P = np.linspace(2, 60, 400)
    for m, col in zip(range(2, 7), ["#1f77b4", "#2ca02c", "#ff7f0e", "#d62728", "#9467bd"]):
        ax.plot(P, A[m - 1] + (m - 1) * P, color=col, lw=1.2, label=f"m = {m}")
    env = np.min([A[m - 1] + (m - 1) * P for m in range(1, len(A) + 1)], axis=0)
    ax.plot(P, env, "k", lw=2.4, label="optimal $T^*(P)$")
    ax.plot(P_mark, np.interp(P_mark, P, env), "ko")
    ax.set(ylim=(4040, 4220), xlabel="pit loss P (s)", ylabel="race time (s)",
           title="A3 - $T^*(P)=\\min_m\\,[A_m+(m-1)P]$")
    ax.legend(frameon=False, fontsize=8)
    m = np.arange(1, len(deltas) + 1)
    bx.step(m, deltas, where="mid", color="#1f4e79", lw=2)
    bx.plot(m, deltas, "o", color="#1f4e79", ms=3)
    bx.axhline(P_mark, color="#c0392b", ls="--", label=f"P = {P_mark:g} s")
    bx.set(yscale="log", xlabel="current stints m", ylabel="$\\Delta_m=A_m-A_{m+1}$ (s)",
           title="Another stop pays off exactly when $\\Delta_m > P$")
    bx.legend(frameon=False)
    _save(fig, path)


def strategy_bars(path: Path, panels: dict):
    """panels: title -> list of (track name, Strategy)."""
    fig, axes = plt.subplots(1, len(panels), figsize=(5.2 * len(panels), 6.2), sharey=True, squeeze=False)
    for ax, (title, rows) in zip(axes[0], panels.items()):
        for y, (name, s) in enumerate(reversed(rows)):
            x = 0
            for c, n in s.stints:
                ax.barh(y, n, left=x, color=COLOR[c], edgecolor="white", height=0.72)
                ax.text(x + n / 2, y, str(n), ha="center", va="center", fontsize=7,
                        color="white" if c != "M" else "black")
                x += n
        ax.set_yticks(range(len(rows)), [n for n, _ in reversed(rows)])
        ax.set(xlabel="lap", title=title)
        ax.grid(axis="y", visible=False)
    handles = [plt.Rectangle((0, 0), 1, 1, color=COLOR[c]) for c in "SMH"]
    fig.legend(handles, [NAME[c] for c in "SMH"], loc="upper center", ncol=3, frameon=False,
               bbox_to_anchor=(0.5, 0.0))
    _save(fig, path)


def trumpet(path: Path, bands: dict):
    fig, ax = plt.subplots(figsize=(7.5, 3.6))
    for c, (k, mean, half) in bands.items():
        ax.plot(k, mean, color=COLOR[c], lw=2, label=NAME[c])
        ax.fill_between(k, mean - half, mean + half, color=COLOR[c], alpha=0.18)
    ax.set(ylim=(78, 100), xlabel="tyre age k", ylabel="lap time (s)",
           title="A5 - 95% band of the lap time (delta method): widens with age, bursts at the cliff")
    ax.legend(frameon=False)
    _save(fig, path)


def parameter_distributions(path: Path, samples: dict, pits: np.ndarray):
    fig, axes = plt.subplots(1, 4, figsize=(12, 2.8))
    for i, (label, unit) in enumerate([("B", "s"), ("d", "s/lap"), ("L", "lap")]):
        for c in "SMH":
            v = samples[c][{"B": 0, "d": 1, "L": 2}[label]]
            if label == "L":
                vals, counts = np.unique(v, return_counts=True)
                axes[i].bar(vals, counts / counts.sum(), color=COLOR[c], alpha=0.6, width=0.9)
            else:
                axes[i].hist(v, bins=80, density=True, color=COLOR[c], alpha=0.55, label=NAME[c])
        axes[i].set(title={"B": "$B_c$ scaled normal", "d": "$d_c$ log-normal",
                           "L": "$L_c$ rounded normal"}[label], xlabel=unit)
    axes[3].hist(pits[pits < 32], bins=120, density=True, color="#34495e")
    axes[3].set(title="$P$ log-logistic", xlabel="s")
    axes[0].legend(frameon=False, fontsize=7)
    _save(fig, path)


def risk_profile(path: Path, sims: dict, table: dict):
    fig, (ax, bx) = plt.subplots(1, 2, figsize=(11, 3.8), gridspec_kw={"width_ratios": [1.6, 1]})
    cols = plt.cm.tab10(np.arange(len(sims)))
    for col, (name, T) in zip(cols, sims.items()):
        h, e = np.histogram(T, bins=160, range=(4000, 4400), density=True)
        ax.plot((e[1:] + e[:-1]) / 2, h, color=col, lw=1.4, label=name)
        r = table[name]
        bx.scatter(r["mean"], r["CVaR"], s=60, color=col)
        bx.annotate(name.rsplit(" ", 1)[0], (r["mean"], r["CVaR"]),
                    xytext=(5, 4), textcoords="offset points", fontsize=8)
    ax.set(xlabel="race time T (s)", ylabel="density", title="A5 - race-time distribution (90 000 race days)")
    ax.legend(frameon=False, fontsize=7.5)
    bx.set(xlabel="E[T] (s)", ylabel="CVaR$_{90}$ (s)", title="Mean vs tail risk (lower-left is better)")
    _save(fig, path)


def calibration(path: Path, table: list):
    fig, (ax, bx) = plt.subplots(1, 2, figsize=(11, 3.6))
    lab = [f"{s['race'][:3]} S{s['stint']} ({s['compound']})" for s in table]
    x = np.arange(len(table))
    ax.bar(x - 0.2, [s["B_raw"] for s in table], 0.4, color="#bbbbbb", label="raw intercept")
    ax.bar(x + 0.2, [s["B_ref"] for s in table], 0.4, color=[COLOR[s["compound"]] for s in table],
           label="after fuel + track correction")
    ax.set(ylim=(74, 100), xticks=x, ylabel="B (s)", title="A6 - baseline per stint")
    ax.set_xticks(x, lab, rotation=45, ha="right", fontsize=7.5)
    ax.legend(frameon=False, fontsize=8)
    bx.bar(x - 0.2, [s["d_raw"] for s in table], 0.4, color="#bbbbbb", label="raw slope")
    bx.bar(x + 0.2, [s["d_corr"] for s in table], 0.4, color=[COLOR[s["compound"]] for s in table],
           label="corrected d")
    bx.axhline(0, color="k", lw=0.8)
    bx.set_xticks(x, lab, rotation=45, ha="right", fontsize=7.5)
    bx.set(ylabel="d (s/lap)", title="Negative Medium slopes vanish after correction")
    bx.legend(frameon=False, fontsize=8)
    _save(fig, path)
